#!/bin/sh
# Generated by `cargo xtask paper fetch-script` from xtask/bench/datasets.toml.
# Do not edit: change datasets.toml and regenerate.
#
# Fetches the paper datasets (D95) and builds the derived inputs. CI never
# runs this. Usage: sh paper/fetch-datasets.sh [NAME]   (NAME: one item)
# GLOCI_BENCH_CACHE sets the cache (default target/bench-data/cache).
#
# Tools the derived inputs need, as pinned in xtask/docker/Dockerfile.bench
# (run this in that image, or install the same versions):
#   rust=1.99.1
#   bedtools=2.31.1
#   bedops=2.4.41
#   vcftools=0.1.16
#   htslib=1.21
#   bcftools=1.21
#   samtools=1.21
#   mosdepth=0.3.10
#   hyperfine=2.0.0
#   bedtk=0.1
#   vcfkit=0.2.9
#   coreutils=9.12
#   gawk=5.3.1
#   time=1.10
#   ucsc-bigwigtobedgraph=469
# Derived commands run with LC_ALL=C under plain sh (no pipefail): a
# truncated pipeline is caught by the sha256 check once it is pinned.
set -eu
ROOT=$(cd "$(dirname "$0")/.." && pwd)
CACHE=${GLOCI_BENCH_CACHE:-$ROOT/target/bench-data/cache}
ONLY=${1:-}
mkdir -p "$CACHE"

want() { [ -z "$ONLY" ] || [ "$ONLY" = "$1" ]; }
md5_of() { if command -v md5sum >/dev/null 2>&1; then md5sum "$1" | cut -d' ' -f1; else md5 -q "$1"; fi; }
sha256_of() { if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1; else shasum -a 256 "$1" | cut -d' ' -f1; fi; }

# fetch NAME URL FILE MD5: the provider's md5 is the check.
fetch() {
  want "$1" || return 0
  if [ ! -e "$CACHE/$3" ]; then
    echo "fetching $1" >&2
    curl -fsSL -o "$CACHE/$3.tmp" "$2"
    mv "$CACHE/$3.tmp" "$CACHE/$3"
  fi
  got=$(md5_of "$CACHE/$3")
  if [ "$got" != "$4" ]; then
    echo "md5 mismatch for $1: expected $4, got $got; delete $CACHE/$3 and run again" >&2
    exit 1
  fi
}

# derive NAME SHA256 COMMAND: COMMAND sees IN, IN2... and OUT.
derive() {
  want "$1" || return 0
  if [ ! -e "$CACHE/$1" ]; then
    echo "deriving $1" >&2
    OUT="$CACHE/$1.partial" LC_ALL=C sh -c "$3"
    mv "$CACHE/$1.partial" "$CACHE/$1"
    for f in "$CACHE/$1.partial".*; do
      if [ -e "$f" ]; then mv "$f" "$CACHE/$1.${f##*.partial.}"; fi
    done
  fi
  if [ -z "$2" ]; then
    echo "TO-PIN: $1 has no sha256 in datasets.toml (got $(sha256_of "$CACHE/$1"))" >&2
  elif [ "$(sha256_of "$CACHE/$1")" != "$2" ]; then
    echo "sha256 mismatch for $1: expected $2; delete $CACHE/$1 and run again" >&2
    exit 1
  fi
}

fetch '1kg-30x-chr20' 'https://ftp.1000genomes.ebi.ac.uk/vol1/ftp/data_collections/1000G_2504_high_coverage/working/20220422_3202_phased_SNV_INDEL_SV/1kGP_high_coverage_Illumina.chr20.filtered.SNV_INDEL_SV_phased_panel.vcf.gz' '1kGP_high_coverage_Illumina.chr20.filtered.SNV_INDEL_SV_phased_panel.vcf.gz' '34a9a5dbfb285e7eb9d1f2881953014b'
fetch 'gencode-v46-gtf' 'https://ftp.ebi.ac.uk/pub/databases/gencode/Gencode_human/release_46/gencode.v46.annotation.gtf.gz' 'gencode.v46.annotation.gtf.gz' '68070e3c87f6a0e70af6e4ff4d55f61c'
fetch 'encode-ccre-v4' 'https://www.encodeproject.org/files/ENCFF420VPZ/@@download/ENCFF420VPZ.bed.gz' 'ENCFF420VPZ.bed.gz' 'ea1820bd71581ba01c94fc600fbf794d'
fetch 'encode-ctcf-k562-peaks' 'https://www.encodeproject.org/files/ENCFF769AUF/@@download/ENCFF769AUF.bed.gz' 'ENCFF769AUF.bed.gz' '7d086cac19c5311a77b7e21e3d931435'
fetch 'encode-ctcf-k562-fc' 'https://www.encodeproject.org/files/ENCFF979PWH/@@download/ENCFF979PWH.bigWig' 'ENCFF979PWH.bigWig' '4a1da9d7819bc622c27cd60950d28abb'
fetch 'gnomad-v4.1-exomes-chr22' 'https://storage.googleapis.com/gcp-public-data--gnomad/release/4.1/vcf/exomes/gnomad.exomes.v4.1.sites.chr22.vcf.bgz' 'gnomad.exomes.v4.1.sites.chr22.vcf.bgz' 'dcf191563e69054a71bd4dc77862799a'
fetch 'encode-ctcf-k562-bam' 'https://www.encodeproject.org/files/ENCFF834MPG/@@download/ENCFF834MPG.bam' 'ENCFF834MPG.bam' '22477d07776b89e20b0458ed873306d4'

export IN="$CACHE/gencode.v46.annotation.gtf.gz"
derive 'exons-unsorted.bed' '' 'zcat "$IN" | gawk -F'\''\t'\'' -v OFS='\''\t'\'' '\''$3=="exon"{match($9,/gene_name "[^"]+"/);print $1,$4-1,$5,substr($9,RSTART+11,RLENGTH-12),0,$7}'\'' > "$OUT"'
export IN="$CACHE/exons-unsorted.bed"
derive 'exons.bed' '' 'sort -k1,1 -k2,2n -s "$IN" > "$OUT"'
export IN="$CACHE/ENCFF420VPZ.bed.gz"
derive 'ccre.bed' '' 'zcat "$IN" | cut -f1-6 | sort -k1,1 -k2,2n -s > "$OUT"'
export IN="$CACHE/ENCFF769AUF.bed.gz"
derive 'ctcf-peaks.bed' '' 'zcat "$IN" | cut -f1-6 | sort -k1,1 -k2,2n -s > "$OUT"'
export IN="$CACHE/ccre.bed"
derive 'ccre.bed.gz' '' 'bgzip -c "$IN" > "$OUT" && tabix -p bed "$OUT"'
export IN="$CACHE/exons.bed"
derive 'exons.bed.gz' '' 'bgzip -c "$IN" > "$OUT" && tabix -p bed "$OUT"'
export IN="$CACHE/ENCFF979PWH.bigWig"
derive 'ctcf-fc.bedgraph' '' 'bigWigToBedGraph "$IN" /dev/stdout | sort -k1,1 -k2,2n -s > "$OUT"'
export IN="$CACHE/1kGP_high_coverage_Illumina.chr20.filtered.SNV_INDEL_SV_phased_panel.vcf.gz"
derive '1kg-chr20.bcf' '' 'bcftools view -Ob -o "$OUT" "$IN" && bcftools index "$OUT"'
export IN="$CACHE/1kGP_high_coverage_Illumina.chr20.filtered.SNV_INDEL_SV_phased_panel.vcf.gz"
derive '1kg-chr20.p1.vcf.gz' '' 'bcftools index -f -t "$IN" && bcftools view -Oz -r chr20:1-30000000 -o "$OUT" "$IN" && bcftools index -t "$OUT"'
export IN="$CACHE/1kGP_high_coverage_Illumina.chr20.filtered.SNV_INDEL_SV_phased_panel.vcf.gz"
derive '1kg-chr20.p2.vcf.gz' '' 'bcftools index -f -t "$IN" && bcftools view -Oz -r chr20:30000001- -o "$OUT" "$IN" && bcftools index -t "$OUT"'
export IN="$CACHE/ENCFF834MPG.bam"
derive 'ctcf-k562.bam' '' 'samtools sort -@ 4 -o "$OUT" "$IN" && samtools index -@ 4 "$OUT"'
export IN="$CACHE/ctcf-k562.bam"
derive 'ctcf-k562.cram' '' 'samtools view -C --output-fmt-option no_ref -@ 4 -o "$OUT" "$IN" && samtools index "$OUT"'
export IN="$ROOT/crates/gloci-io/data/genomes/hg38.genome"
derive 'hg38.lex.genome' '' 'sort -k1,1 "$IN" > "$OUT"'
